PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'customer',suspended INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS content(id TEXT PRIMARY KEY,section TEXT NOT NULL CHECK(section IN ('movies','drama','tv','anime','cartoons','cricket','sports','videos')),title TEXT NOT NULL,data TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'draft',file TEXT,validated INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS uploads(id TEXT PRIMARY KEY,content_id TEXT REFERENCES content(id),size INTEGER NOT NULL,offset INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'uploading');
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,content_id TEXT REFERENCES content(id),state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,error TEXT,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY,actor TEXT,action TEXT NOT NULL,target TEXT,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS grants(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS progress(user_id TEXT REFERENCES users(id),content_id TEXT REFERENCES content(id),position REAL NOT NULL,PRIMARY KEY(user_id,content_id));
CREATE TABLE IF NOT EXISTS watchlist(user_id TEXT REFERENCES users(id),content_id TEXT REFERENCES content(id),PRIMARY KEY(user_id,content_id));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,section TEXT,authorized INTEGER NOT NULL DEFAULT 0,created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS identities(subject TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS oauth_states(state TEXT PRIMARY KEY,nonce TEXT NOT NULL,verifier TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS import_runs(id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(id),state TEXT NOT NULL,cursor INTEGER NOT NULL DEFAULT 0,imported INTEGER NOT NULL DEFAULT 0,duplicates INTEGER NOT NULL DEFAULT 0,review INTEGER NOT NULL DEFAULT 0,errors TEXT NOT NULL DEFAULT '[]',created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_review(id TEXT PRIMARY KEY,run_id TEXT REFERENCES import_runs(id),data TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,kids INTEGER NOT NULL DEFAULT 0,max_age INTEGER NOT NULL DEFAULT 18,pin TEXT,attempts INTEGER NOT NULL DEFAULT 0,locked_until INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS session_profiles(token TEXT PRIMARY KEY REFERENCES sessions(token) ON DELETE CASCADE,profile_id TEXT REFERENCES profiles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS profile_progress(profile_id TEXT REFERENCES profiles(id) ON DELETE CASCADE,content_id TEXT REFERENCES content(id),position REAL NOT NULL,PRIMARY KEY(profile_id,content_id));
CREATE TABLE IF NOT EXISTS profile_watchlist(profile_id TEXT REFERENCES profiles(id) ON DELETE CASCADE,content_id TEXT REFERENCES content(id),PRIMARY KEY(profile_id,content_id));
CREATE TABLE IF NOT EXISTS account_verification(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS email_tokens(token TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,purpose TEXT NOT NULL,expires INTEGER NOT NULL);
